    cameraMat.MakeLookInternal(2, lookDir, 1, (const Math::Vector&)Math::vec4OneY);
    cameraMat.SetPos((const Math::Vector&)Math::vec4Zero);
    cameraMat.SetPos(eyePos);

    for (int i = 0; i < 4; i++) {
        Graphics::Viewport& vp = viewports[i].viewport3D;
        vp.Create();
        vp.zmin = 0.0625f;
        vp.zmax = 1.0f;
        vp.cameraMat = cameraMat;
        vp.rendering = false;
        vp.visibleMask = (1 << (i + 8)) | 1;
        vp.wiiRGBA6 = true;
    }

    viewports[0].viewport3D.SetRelativeCorner(0.0f, 0.0f, 1.0f, 1.0f);

    for (int i = 0; i < 4; i++) {
        viewports[i].viewport3D.parent = &screenView;
        screenView.viewports.PushBack(&viewports[i].viewport3D.listNode);
    }
    for (int i = 0; i < 4; i++) {
        viewports[i].viewportUI.parent = &screenView;
        screenView.viewports.PushBack(&viewports[i].viewportUI.listNode);
    }
    ViewportFullUI.parent = &screenView;
    screenView.viewports.PushBack(&ViewportFullUI.listNode);

    float fovy = 0.7853982f;
    float aspect;
    float znear = 0.01f;
    float zfar = 300.0f;
    float pixelAspect = SCGetAspectRatio() == 1 ? 1.2666667f : 0.95f;

    ViewportFullUI.pixel_aspect = pixelAspect;
    for (int i = 0; i < 4; i++) {
        viewports[i].viewportUI.pixel_aspect = pixelAspect;
        viewports[i].viewport3D.pixel_aspect = pixelAspect;
    }

    aspect = 1.3333334f;
    for (int i = 0; i < 4; i++) {
        viewports[i].viewport3D.SetPerspProjectionZ(fovy, aspect, znear, zfar);
    }
