void zViewportDisableSplitScreens() {
    for (int ii = 0; ii < splitscreenCount; ii++) {
        viewports[ii].viewportUI.AmendRendering(false);
        viewports[ii].viewport3D.AmendRendering(false);
        viewports[ii].isActive = false;
    }
    splitscreenDisabled = true;
}

void zViewportEnableSplitScreens() {
    for (int ii = 0; ii < splitscreenCount; ii++) {
        viewports[ii].viewportUI.AmendRendering(true);
        viewports[ii].viewport3D.AmendRendering(true);
        viewports[ii].isActive = true;
    }
    splitscreenDisabled = false;
}

void zViewportSetSplitScreenMode(int count,
                                 eSplitScreenOrientation orientation) {
    if (splitscreenCount != count || splitscreenOrientation != orientation) {
        for (int ii = count; ii < splitscreenCount; ii++) {
            viewports[ii].viewportUI.AmendRendering(false);
            viewports[ii].viewport3D.AmendRendering(false);
            viewports[ii].isActive = false;
        }

        switch (count) {
        case 1:
            viewports[0].viewportUI.AmendRelativeCorner(0.0f, 0.0f, 1.0f, 1.0f);
            viewports[0].viewport3D.AmendRelativeCorner(0.0f, 0.0f, 1.0f, 1.0f);
            break;
        case 2:
            if (orientation == HORIZONTAL) {
                viewports[0].viewportUI.AmendRelativeCorner(0.0f, 0.0f, 1.0f,
                                                            0.5f);
                viewports[0].viewport3D.AmendRelativeCorner(0.0f, 0.0f, 1.0f,
                                                            0.5f);
                viewports[1].viewportUI.AmendRelativeCorner(0.0f, 0.5f, 1.0f,
                                                            1.0f);
                viewports[1].viewport3D.AmendRelativeCorner(0.0f, 0.5f, 1.0f,
                                                            1.0f);
            } else {
                viewports[0].viewportUI.AmendRelativeCorner(0.0f, 0.0f, 0.5f,
                                                            1.0f);
                viewports[0].viewport3D.AmendRelativeCorner(0.0f, 0.0f, 0.5f,
                                                            1.0f);
                viewports[1].viewportUI.AmendRelativeCorner(0.5f, 0.0f, 1.0f,
                                                            1.0f);
                viewports[1].viewport3D.AmendRelativeCorner(0.5f, 0.0f, 1.0f,
                                                            1.0f);
            }
            break;
        case 4:
            viewports[0].viewportUI.AmendRelativeCorner(0.0f, 0.0f, 0.5f, 0.5f);
            viewports[0].viewport3D.AmendRelativeCorner(0.0f, 0.0f, 0.5f, 0.5f);
            viewports[1].viewportUI.AmendRelativeCorner(0.5f, 0.0f, 1.0f, 0.5f);
            viewports[1].viewport3D.AmendRelativeCorner(0.5f, 0.0f, 1.0f, 0.5f);
            viewports[2].viewportUI.AmendRelativeCorner(0.0f, 0.5f, 0.5f, 1.0f);
            viewports[2].viewport3D.AmendRelativeCorner(0.0f, 0.5f, 0.5f, 1.0f);
            viewports[3].viewportUI.AmendRelativeCorner(0.5f, 0.5f, 1.0f, 1.0f);
            viewports[3].viewport3D.AmendRelativeCorner(0.5f, 0.5f, 1.0f, 1.0f);
            break;
        }

        if (!splitscreenDisabled) {
            for (int ii = splitscreenCount; ii < count; ii++) {
                viewports[ii].viewportUI.AmendRendering(true);
                viewports[ii].viewport3D.AmendRendering(true);
                viewports[ii].isActive = true;
            }
        }

        splitscreenCount = count;
        splitscreenOrientation = orientation;

        Scaleform::SFWrap_RefreshViewports();
    }
}

