// NEAR MISS: 6 of 76 words; the camera-space point's two divisions take
// their float registers the other way round (retail f1/f4 and f0/f2).
// Row reference locals in either order and a reflowed call did not move it.
void zViewportScreenToWorldDir(int index, const xVec2& screenPoint,
                               xVec3& direction) {
    zViewport& vp = viewports[index];
    Graphics::ViewMatrix projMat(vp.viewport3D.viewMat[1]);
    xMat4x3 viewOG = vp.zcam.camGroup.mat;
    Math::Matrix33 viewMat;
    viewMat.Assign(viewOG.right.x, viewOG.right.y, viewOG.right.z, viewOG.up.x,
                   viewOG.up.y, viewOG.up.z, viewOG.at.x, viewOG.at.y,
                   viewOG.at.z);

    Math::Vector screenPointInCameraSpace(-screenPoint.x / projMat.mat.v[0].data.x,
                                          screenPoint.y / projMat.mat.v[1].data.y,
                                          1.0f);

    Math::Vector rayOrigin(viewOG.pos.x, viewOG.pos.y, viewOG.pos.z);
    Math::Vector rayDir;
    PSMTXMultVecSR(&viewMat, &screenPointInCameraSpace, &rayDir);
    rayDir = rayDir.Normalize();

    __ct__Q24Math6VectorFfff(&direction, rayDir.data.x, rayDir.data.y, rayDir.data.z);
}

