void zScaleform::DoHandleEvent(xBase* from, unsigned int toEvent,
                               Sext::EventAny* params) {
    if (moviePlaying && toEvent == 0x99F7FD6C) {
        ReadInput(true);
    }

    if (Graphics::HasMovie() && Graphics::IsMovieFullScreen()) {
        if (toEvent == 0x0ACC48B8) {
            deferPlayMovie = true;
        }
        zUI::DoHandleEvent(from, toEvent, params);
        return;
    }

    float args[4];
    args[0] = port;

    switch (toEvent) {
    case 0x0ACC48B8:
        Play();
        break;
    case 0x85151A66:
        Scaleform::SFWrap_Pause(this);
        break;
    case 0x26B1D67D:
        Scaleform::SFWrap_Unpause(this);
        if (!TRC::trcModule->saveLoad.IsSaveSystemBusy()) {
            Scaleform::SFWrap_InvokeASFunc(this, "_root.driver.autosavingStop",
                                           0, (float*)0);
        }
        break;
    case 0x0B3550F2:
        Stop();
        break;
    case 0xAE72E9E5:
        Clear();
        break;
    case 0x27858BA2:
        Unclear();
        break;
    case 0x5D13683F:
        zUIMgrEnablePause(true);
        break;
    case 0x48DE9A7E:
        zUIMgrEnablePause(false);
        break;
    case 0x715338DA:
        Scaleform::SFWrap_InvokeASFunc(this, "_root.subMenu.SaveLoadDone", 0,
                                       (float*)0);
        break;
    case 0xC46D20ED:
        Scaleform::SFWrap_InvokeASFunc(this, "_root.subMenu.SaveLoadFailed", 0,
                                       (float*)0);
        break;
    case 0x3FECFE14:
        Scaleform::SFWrap_InvokeASFunc(this, "_root.subMenu.SaveLoadDisabled",
                                       0, (float*)0);
        break;
    case 0x611F16F2:
        Scaleform::SFWrap_InvokeASFunc(this, "_root.subMenu.SaveLoadRefresh",
                                       0, (float*)0);
        break;
    case 0xCB5A45D5:
        if (asset->movieType == 1) {
            float arg = params->value;
            Scaleform::SFWrap_InvokeASFunc(this, "EnableMask", 1, &arg);
        }
        break;
    case 0x59DCA4FA:
        if (asset->movieType == 1) {
            float arg = params->value;
            Scaleform::SFWrap_InvokeASFunc(this, "DisableMask", 1, &arg);
        }
        break;
    case 0x31D838EC:
        if (asset->movieType == 1) {
            float arg = params->value;
            Scaleform::SFWrap_InvokeASFunc(this, "HideMask", 1, &arg);
        }
        break;
    case 0xB91F39D5:
        Scaleform::SFWrap_InvokeASFunc(this, "_level0.SignInChanged", 0,
                                       (float*)0);
        break;
    case 0x80AEA888:
        ReadInput(true);
        break;
    case 0x8E652991:
        Scaleform::SFWrap_SetButtonState(this, 0, false);
        break;
    }

    zUI::DoHandleEvent(from, toEvent, params);
}

void zScaleform::DoReset() {
    zUI::DoReset();
    visible = true;
}

void zScaleform::DoUpdate(float dt) {
    if (zScaleformNS::SB09Hack_disableMotionPlus) {
        Scaleform::SFWrap_BroadcastEvent((Scaleform::eSFEventType)36);
        zScaleformNS::SB09Hack_disableMotionPlus = false;
    }

    if (UIMgr::returningToTitle) {
        bool alreadyExiting = zGameStateGet() == 10;
        bool inTrcPauseMode = zGameStateGet() == 3;

        if (globals.sceneCur->sceneID != 'MNUS') {
            if (!alreadyExiting && !inTrcPauseMode) {
                zGameStateSwitchEvent((Sext::eGameStateCombined)7);
                TRC::trcModule->saveLoad.SetSaveEnabled(false);
                globals.sceneCur->pendingPortal.Set(SCENE_LAYER_MNUS);
                TRC::trcModule->saveLoad.SetSaveEnabled(true);
            } else if (inTrcPauseMode && asset->movieType == 2) {
                ReadInput(false);
            }
        } else {
            UIMgr::returningToTitle = false;
        }
    } else if (deferPlayMovie) {
        if (!Graphics::HasMovie() || !Graphics::IsMovieFullScreen()) {
            deferPlayMovie = false;
            Play();
        }
    } else if (zUI::bAllowInput) {
        // NEAR MISS: 1 word shape (then 43 words shifted, 4 bytes short);
        // retail `beq +8 ; b epilogue` for this return, ours folds it to one
        // `bne`. Tried: braces, an empty then with else, the negated test
        // in the else-if, and `!bAllowInput || (...)` with an empty then.
        if (Graphics::HasMovie() && Graphics::IsMovieFullScreen()) {
            return;
        }

        if (stoppedMovieCounter != 0) {
            zEntEvent(dispatcher->id, 0x0B3550F2, 0);
            stoppedMovieCounter = 0;
        }

        if (moviePlaying) {
            if (asset->movieType != 5) {
                if (!g_gameInterface.IsMessageBoxVisible() ||
                    asset->movieType == 1 || asset->movieType == 2) {
                    ReadInput(false);
                }
            }
        }
    }
}

void TRC::SaveLoadBase::SetSaveEnabled(bool value) { saveEnabled = value; }

// NEAR MISS: the pad-state copy. Retail inlines IO::PadInput's implicit copy
// (328 bytes, calling IO::PadStick's and IO::PadTilt's copies); ours will not
// inline it -- always_inline and an earlier inline user of the copy leave it
// a call -- so the copy is declared on PadInput and called, and the two weak
// copies it would call (PadStick matched when emitted) are not emitted.
void zScaleform::ReadInput(bool initState) {
    int readPads = curPads;
    if (readPads & 0x80) {
        readPads = zUIMgrGetActivePadMask();
    }

    bool pointerIsDisabled = false;
    int readPointers = curPointers;
    if (readPointers & 0x80) {
        readPointers = zUIMgrGetActivePadMask();
    }

    if (asset->movieType == 1) {
        int disabledPointers = zUIMgrGetPointerDisabled();
        if (disabledPointers & pointerActiveLastFrame) {
            int arg = disabledPointers & pointerActiveLastFrame;
            Scaleform::SFWrap_InvokeASFunc(this, "DisableMask", 1, &arg);
            pointerActiveLastFrame &= ~arg;
        } else if (~(disabledPointers | pointerActiveLastFrame) & 0xF) {
            int arg = ~(disabledPointers | pointerActiveLastFrame) & 0xF;
            Scaleform::SFWrap_InvokeASFunc(this, "EnableMask", 1, &arg);
            pointerActiveLastFrame |= arg;
        }
    } else if (zUIMgrIsPointerDisabled(readPads)) {
        readPointers = 0;
        pointerIsDisabled = true;
    }

    int buttonInput = 0;
    for (int i = 0; i < 4; i++) {
        IO::Pad* pad = IO::GetAttachedPadFromPort(i);
        if (pad != 0) {
            IO::PadInput padInput = pad->istate;

            if ((readPads & (1 << i)) ||
                (i == 0 && TRC::trcModule->trcPadManager.CheckEscapable())) {
                buttonInput |= padInput.flags;
                if (padInput.stick[0].off.data.x < -0.5f) {
                    buttonInput |= 4;
                } else if (padInput.stick[0].off.data.x > 0.5f) {
                    buttonInput |= 8;
                }
                if (padInput.stick[0].off.data.y < -0.5f) {
                    buttonInput |= 0x20;
                } else if (padInput.stick[0].off.data.y > 0.5f) {
                    buttonInput |= 0x10;
                }
            }

            if (padInput.flags & 0x3C) {
                zUIMgrResetDisabledPointerTimer(i);
            }

            if ((readPointers & (1 << i)) && !pointerIsDisabled) {
                float xpos;
                float ypos;
                int buttons = 0;
                if (padInput.irPointer.status != 2) {
                    xpos = ypos = -10.0f;
                } else {
                    xpos = padInput.irPointer.x;
                    ypos = padInput.irPointer.y;
                }
                if (padInput.flags & 0x1000) {
                    buttons |= 1;
                }
                Scaleform::SFWrap_SetMouseState(this, i, xpos, ypos, buttons);
            } else {
                float xpos = -10.0f;
                float ypos = -10.0f;
                Scaleform::SFWrap_SetMouseState(this, i, xpos, ypos, 0);
            }
        } else {
            float offScreenPos = -10.0f;
            Scaleform::SFWrap_SetMouseState(this, i, offScreenPos, offScreenPos,
                                            0);
        }
    }

    if (zGameModeGet() == 1 && asset->movieType != 1 &&
        asset->movieType != 2 && asset->movieType != 4) {
        initState = true;
    }

    Scaleform::SFWrap_SetButtonState(this, buttonInput, initState);
}

