void zScaleform::sendEvent(void* userData, const char* eventName,
                           const char* params) {
    strlen(eventName);

    const char* eventSubType = eventName + 5;

    switch (eventName[0] << 24 | eventName[1] << 16 | eventName[2] << 8 |
            eventName[3]) {
    case 'MENU':
        if (strcmp(eventSubType, "Stop") == 0) {
            Stop();
        }

        if (strcmp(eventSubType, "Restart") == 0) {
            Stop();
            zSoundModule::SoundCategoryStopAllEvents("UI");
            zSoundModule::SoundCategoryStopAllEvents("UImusic");
            zSoundModule::SoundCategoryStopAllEvents("UIdialog");
            zSoundModule::SoundCategoryStopAllEvents("UIcine");
            Play();
        } else if (strcmp(eventSubType, "AnimFinished") == 0) {
            if (strcmp(params, "MessageBoxOut") == 0) {
                g_gameInterface.MessageBoxClosed();
            } else if (strcmp(params, "MessageBoxIn") == 0) {
                g_gameInterface.MessageBoxOpened();
            }
        } else if (strcmp(eventSubType, "SetSubtitlesEnabled") == 0) {
            globals.option_subtitles = strcmp(params, "true") == 0;
        } else if (strcmp(eventSubType, "PlayAttractVideo") == 0) {
            if (!g_gameInterface.IsMessageBoxVisible()) {
                EventActionPlayMovie eventParams;
                eventParams.param0 = 100;
                eventParams.paramSkippable = 2;
                zEntEvent(dispatcher->id, 0xEC3F0680,
                          (Sext::EventAny*)&eventParams);
            }
        } else if (strcmp(eventSubType, "PlayMotionPlusVideo") == 0) {
            VISetBlack(1);
            VIFlush();
            VIWaitForRetrace();
            OSExecl("/sys/mpls_movie/player.dol", "", "", "ASPECT_RATIO_AUTO",
                    0);
        } else if (strcmp(eventSubType, "PlayVideo") == 0) {
            EventActionPlayMovie eventParams;
            eventParams.param0 = atoi(params);

            char subtitle[29];
            snprintf(subtitle, 29, "Movie%s_Subtitles_reference", params);
            uid subtitleID = xUIDMgrFindUID(xStrHash(subtitle));
            eventParams.paramSubtitles =
                subtitleID > 0xFFFFFFFFULL
                    ? subtitleID
                    : ((subtitleID << 8) >> 32 & 0xFF) << 32 |
                          (subtitleID & 0xFFFFFF);

            eventParams.paramSkippable = 2;
            zEntEvent(dispatcher->id, 0xEC3F0680,
                      (Sext::EventAny*)&eventParams);
        } else if (strcmp(eventSubType, "EnableCheatEntry") == 0) {
        } else if (strcmp(eventSubType, "ShowSellScreen") == 0) {
            zScaleform* sellScreen =
                (zScaleform*)zSceneFindObject("DEMO_SellScreen_reference");
            sellScreen->Play();
        } else if (strcmp(eventSubType, "ExitDemo") == 0) {
            System::gSysForceExit = true;
        }
        break;

    case 'CHTS':
        if (strcmp(eventSubType, "EnableCheat") == 0) {
            int cheatIndex = atoi(params);
            zCheatProcess((eCheats)cheatIndex, true);
        } else if (strcmp(eventSubType, "DisableCheat") == 0) {
            int cheatIndex = atoi(params);
            zCheatProcess((eCheats)cheatIndex, false);
        } else if (strcmp(eventSubType, "UnlockCheat") == 0) {
            int cheatIndex = atoi(params);
            zCheatUnlock((eCheats)cheatIndex);
        }

    case 'CTRL':
        if (strcmp(eventSubType, "GetPadLock") == 0) {
            zUIMgrSetActivePadMask(1);
            UIMgr::noPressStart = false;
            globals.playerPort = 0;
        } else if (strcmp(eventSubType, "ClearPadLock") == 0) {
            TRC::trcModule->trcPadManager.DisableAllPadActivity();
        } else if (strcmp(eventSubType, "EnforceTRC") == 0) {
            TRC::trcModule->trcPadManager.EnforcePadActivity(globals.playerPort);
        } else if (strcmp(eventSubType, "WiiTRCBackOut") == 0) {
            TRC::trcModule->trcPadManager.SetEscapable(1);
        } else if (strcmp(eventSubType, "WiiTRCBackOutOver") == 0) {
            TRC::trcModule->trcPadManager.SetEscapable(0);
        } else if (strcmp(eventSubType, "WiiAllOpen") == 0) {
            TRC::trcModule->trcPadManager.SetupInitialAccessory(
                globals.playerPort);
        } else if (strcmp(eventSubType, "WiiNotWaiting") == 0) {
            TRC::trcModule->trcPadManager.ClearInitialAccessoryPrep(
                globals.playerPort);
        } else if (strcmp(eventSubType, "MotionReady") == 0) {
            TRC::trcModule->trcPadManager.SetLockToHolding(1);
        } else if (strcmp(eventSubType, "MotionSelected") == 0) {
            TRC::trcModule->trcPadManager.SetLockToHolding(0);
        } else if (strcmp(eventSubType, "WiiAllWaiting") == 0) {
            TRC::trcModule->trcPadManager.DisablePadTRC(globals.playerPort);
            TRC::trcModule->trcPadManager.SetupInitialAccessoryPrep(
                globals.playerPort);
        } else if (strcmp(eventSubType, "ClearTRC") == 0) {
            TRC::trcModule->trcPadManager.DisableAllPadActivity();
        } else if (strcmp(eventSubType, "EnableTRC") == 0) {
            unsigned int idx = atoi(params);
            TRC::trcModule->trcPadManager.EnforcePadActivity(idx);
            if (!TRC::trcModule->trcPadManager.CheckPadAccessoryChangeConfirm(
                    idx)) {
                TRC::trcModule->trcPadManager.EnableAccessoryActivity(
                    idx, TRC::TRCPadManager::ACCESSORY_1);
            }
        } else if (strcmp(eventSubType, "DisableTRC") == 0) {
            unsigned int idx = atoi(params);
            TRC::trcModule->trcPadManager.DisablePadActivity(idx);
        } else if (strcmp(eventSubType, "ConfirmConfirm") == 0) {
            unsigned int idx = atoi(params);
            bool needReassign =
                TRC::trcModule->trcPadManager.CheckInitialAccessoryPrep(
                    globals.playerPort);
            TRC::trcModule->trcPadManager.SetPadAccessoryConfirm(idx);
            if (needReassign) {
                if (TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                        globals.playerPort, TRC::TRCPadManager::ACCESSORY_1)) {
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v48();
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v55();
                    TRC::trcModule->trcPadManager.EnableAccessoryActivity(
                        globals.playerPort, TRC::TRCPadManager::ACCESSORY_1);
                } else if (TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                               globals.playerPort,
                               (TRC::TRCPadManager::AccessoryType)4)) {
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v48();
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v50();
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v54();
                } else {
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v55();
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v50();
                    zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v47();
                }
            }
        } else if (strcmp(eventSubType, "WaitForConfirm") == 0) {
            unsigned int idx = atoi(params);
            TRC::trcModule->trcPadManager.SetPadAccessoryChangeConfirm(idx, 1);
        } else if (strcmp(eventSubType, "ClearConfirm") == 0) {
            unsigned int idx = atoi(params);
            TRC::trcModule->trcPadManager.SetPadAccessoryChangeConfirm(idx, 0);
        } else if (strcmp(eventSubType, "RevertConfirm") == 0) {
            if (TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                    globals.playerPort, TRC::TRCPadManager::ACCESSORY_1)) {
                IO::PadNative::DPDOff();
            }
            atoi(params);
            zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v50();
            zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v55();
            zPlayerInputNS::GetPadAtGamePort(globals.playerPort)->_v48();
        } else if (strcmp(eventSubType, "SetRumbleState") == 0) {
            bool rumbleEnabled = strcmp(params, "true") == 0;
            int readPads = curPads;
            if (readPads & 0x80) {
                readPads = zUIMgrGetActivePadMask();
            }
            for (int i = 0; i < 4; i++) {
                xRumble::Manager::Get()->EnableRumbling(i, rumbleEnabled);
                if (xTRCPadIsPort(i, (_tagTRCState)3) && rumbleEnabled &&
                    rumbleEmitter != 0 && (readPads & (1 << i))) {
                    xRumble::Manager::Get()->Add(0, i, rumbleEmitter);
                }
            }
        } else if (strcmp(eventSubType, "EnablePointers") == 0) {
            EventActionPointerControl eventParams;
            eventParams.Pointers = atoi(params);
            zEntEvent(dispatcher->id, 0xCB5A45D5,
                      (Sext::EventAny*)&eventParams);
        } else if (strcmp(eventSubType, "DisablePointers") == 0) {
            EventActionPointerControl eventParams;
            eventParams.Pointers = atoi(params);
            zEntEvent(dispatcher->id, 0x59DCA4FA,
                      (Sext::EventAny*)&eventParams);
        } else if (strcmp(eventSubType, "HidePointers") == 0) {
            EventActionPointerControl eventParams;
            eventParams.Pointers = atoi(params);
            zEntEvent(dispatcher->id, 0x31D838EC,
                      (Sext::EventAny*)&eventParams);
        } else if (strcmp(eventSubType, "AddInput") == 0) {
            unsigned int idx = atoi(params);
            curPads |= 1 << idx;
            curPointers |= 1 << idx;
        } else if (strcmp(eventSubType, "RemoveInput") == 0) {
            unsigned int idx = atoi(params);
            curPads &= ~(1 << idx);
            curPointers &= ~(1 << idx);
        } else if (strcmp(eventSubType, "ClearInput") == 0) {
            curPads = 0;
            curPointers = 0;
        } else if (strcmp(eventSubType, "ResetInput") == 0) {
            curPads = asset->padInput;
            curPointers = asset->pointerInput;
        } else if (strcmp(eventSubType, "StartWiiMotionPlusCalibration") == 0) {
            int gamePort;
            gamePort = strcmp(params, "") ? atoi(params) : globals.playerPort;
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v60();
        } else if (strcmp(eventSubType, "EnableMotionPlus") == 0) {
            int gamePort;
            gamePort = strcmp(params, "") ? atoi(params) : globals.playerPort;
            bool usesExtension = true;
            if (gamePort == 1) {
                usesExtension = false;
            }
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v56(usesExtension);
        } else if (strcmp(eventSubType, "DisableMotionPlus") == 0) {
            int gamePort;
            gamePort = strcmp(params, "") ? atoi(params) : globals.playerPort;
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v57();
        } else if (strcmp(eventSubType, "EnableWiiNunchuck") == 0) {
            int gamePort;
            if (strcmp(params, "")) {
                gamePort = atoi(params);
            } else {
                gamePort = globals.playerPort;
            }
            if (gamePort == globals.playerPort &&
                !TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                    globals.playerPort, TRC::TRCPadManager::ACCESSORY_1)) {
                IO::PadNative::DPDOn();
            }
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v48();
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v55();
            TRC::trcModule->trcPadManager.EnableAccessoryActivity(
                gamePort, TRC::TRCPadManager::ACCESSORY_1);
        } else if (strcmp(eventSubType, "EnableWiiClassicController") == 0) {
            int gamePort;
            if (strcmp(params, "")) {
                gamePort = atoi(params);
            } else {
                gamePort = globals.playerPort;
            }
            if (gamePort == globals.playerPort &&
                TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                    globals.playerPort, TRC::TRCPadManager::ACCESSORY_1)) {
                IO::PadNative::DPDOff();
            }
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v47();
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v50();
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v55();
        } else if (strcmp(eventSubType, "EnableGamecubeController") == 0) {
            int gamePort;
            if (strcmp(params, "")) {
                gamePort = atoi(params);
            } else {
                gamePort = globals.playerPort;
            }
            if (gamePort == globals.playerPort &&
                TRC::trcModule->trcPadManager.CheckAccessoryActivity(
                    globals.playerPort, TRC::TRCPadManager::ACCESSORY_1)) {
                IO::PadNative::DPDOff();
            }
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v54();
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v50();
            zPlayerInputNS::GetPadAtGamePort(gamePort)->_v48();
        } else if (strcmp(eventSubType, "DPDForceOff") == 0) {
            IO::PadNative::DPDForceOff();
        } else if (strcmp(eventSubType, "DPDOn") == 0) {
            IO::PadNative::DPDOn();
        }
        break;

    case 'GAME':
        if (strcmp(eventSubType, "Unpause") == 0) {
            if (!g_gameInterface.IsMessageBoxVisible()) {
                zGameStateSwitchEvent((Sext::eGameStateCombined)7);
            }
        } else if (strcmp(eventSubType, "ControlOn") == 0) {
            zEntEventAllOfType(0, 0, 0xA7CE2290, 0, 85, (ForceEvent)1);
        } else if (strcmp(eventSubType, "Quit") == 0) {
            if (zGameModeGet() == 1) {
                zGameStateSwitchEvent((Sext::eGameStateCombined)7);
            }
            globals.sceneCur->pendingPortal.Set(SCENE_LAYER_MNUS);
            TRC::trcModule->trcPadManager.DisableAllPadActivity();
            TRC::trcModule->trcPadManager.EnforcePadActivity(globals.playerPort);
            TRC::trcModule->trcPadManager.DisablePadTRC(globals.playerPort);
            globals.player2Port = -1;
            TRC::trcModule->saveLoad.ForceNextSave();
            zSceneSaveGameIfPossible();
        } else if (strcmp(eventSubType, "ActivatePortalWidget") == 0) {
            zPortal* ctr = (zPortal*)zSceneFindObject(params);
            if (ctr != 0) {
                EventActionTeleportPlayer p;
                p.ForceSameScene = false;
                p.SameScene = false;
                zEntEvent(this, 0, ctr, 0x369498B4, (Sext::EventAny*)&p,
                          (ForceEvent)1);
            }
        } else if (strcmp(eventSubType, "Portal") == 0) {
            if (zGameModeGet() == 1) {
                zGameStateSwitchEvent((Sext::eGameStateCombined)7);
            }
            globals.sceneCur->pendingPortal.Set(params);
        } else if (strcmp(eventSubType, "PortalToIndex") == 0) {
            if (zGameModeGet() == 1) {
                zGameStateSwitchEvent((Sext::eGameStateCombined)7);
            }
            int levelIdx = atoi(params);
            char* level = zDispatcher_FindLevelStrByIndex(levelIdx);
            globals.sceneCur->pendingPortal.Set(level);
            if (levelIdx == zSceneGetLevelIndex()) {
                if (globals.maxLevelUnlocked == levelIdx) {
                    zCheckpoint::currentActivePtr = 0;
                }
            }
            globals.loadSavedCheckpoint = false;
            if (globals.sceneCur->sceneID ==
                zDispatcher_FindLevelIDByIndex(levelIdx)) {
                zCheckpoint::SceneInit(globals.sceneCur);
            }
        } else if (strcmp(eventSubType, "Start") == 0) {
            char* level =
                zDispatcher_FindLevelStrByIndex(globals.maxLevelUnlocked);
            if (level == 0) {
                level = zDispatcher_FindLevelStrByIndex(0);
            } else {
                globals.loadSavedCheckpoint = true;
            }
            globals.sceneCur->pendingPortal.Set(level);
        } else if (strcmp(eventSubType, "SetSubGameType") == 0) {
            globals.subGameType = atoi(params);
        }
        break;

    case 'PROF':
        if (strcmp(eventSubType, "ShowSigninChangedMsgBoxIfNeeded") == 0) {
        } else if (strcmp(eventSubType, "IgnoreSignIn") == 0) {
        }
        break;

    case 'LOAD':
        if (strcmp(eventSubType, "SetReadyForTermination") == 0) {
            gNGLoadingScreen.readyForTermination = true;
        }
        break;

    case 'MPLY':
        if (strcmp(eventSubType, "StartGame") == 0) {
        }
        break;

    case 'SYSM':
        if (strcmp(eventSubType, "Yes") == 0) {
            TRC::MsgBoxManager::Instance()->Response(
                (TRC::TRCMsgBox::ResponseType)1);
        } else if (strcmp(eventSubType, "No") == 0) {
            TRC::MsgBoxManager::Instance()->Response(
                (TRC::TRCMsgBox::ResponseType)2);
        }
        break;

    case 'SYST':
        if (strcmp(eventSubType, "SetLanguage") == 0) {
            xSTSetLocalizationCode(params);
        } else if (strcmp(eventSubType, "ForceGarbageCollect") == 0) {
            Scaleform::SFWrap_ForceGarbageCollect(this);
        }
        break;

    case 'PLYR':
        if (strcmp(eventSubType, "IncreaseMaxHealth") == 0) {
            EventActionHealth eventParams;
            eventParams.param0 = 2.0f;
            zEntEvent(0, 0, zBoardPlayer::GetInstance(), 0x4CCD7CE1,
                      (Sext::EventAny*)&eventParams, (ForceEvent)1);
        } else if (strcmp(eventSubType, "ControlOff") == 0) {
            zEntEvent(0, 0, zBoardPlayer::GetInstance(), 0xDE7BABDE, 0,
                      (ForceEvent)1);
        }

    case 'SAVE':
        if (strcmp(eventSubType, "SaveData") == 0) {
            if (*params) {
                xglobals->autoSaveSlot = atoi(params);
            }
            globals.needAutoSave = true;
            globals.autoSaveRequestor = this;
        } else if (strcmp(eventSubType, "LoadData") == 0) {
            globals.forceSelectDevice = false;
            xglobals->autoSaveSlot = atoi(params);
            zSaveLoadEventCB(this, 0, 0x54FEA4E2, 0);
            zCheatRemoveAll();
        } else if (strcmp(eventSubType, "SaveReset") == 0) {
            zSaveReset();
        } else if (strcmp(eventSubType, "SetAutoSaveSlot") == 0) {
            xglobals->autoSaveSlot = atoi(params);
        } else if (strcmp(eventSubType, "ClearAutoSaveSlot") == 0) {
            xglobals->autoSaveSlot = 0;
        } else if (strcmp(eventSubType, "DeleteData") == 0) {
            EventActionOneInt intParam;
            intParam.param0 = atoi(params);
            zSaveLoadEventCB(this, 0, 0x17E93B23, (Sext::EventAny*)&intParam);
        } else if (strcmp(eventSubType, "EnableSave") == 0) {
            TRC::trcModule->saveLoad.SetSaveEnabled(true);
        } else if (strcmp(eventSubType, "EnterLoadScreen") == 0) {
            zCheatRemoveAll();
            xglobals->autoSaveSlot = 0;
            Graphics::ResetFirstTimeMovieStatus();
            zSaveLoadEventCB(this, 0, 0x611F16F2, 0);
        } else if (strcmp(eventSubType, "ChangeStorageDevice") == 0) {
        } else if (strcmp(eventSubType, "DisableSave") == 0) {
            xglobals->autoSaveSlot = 0;
        }
        break;

    case 'SNDS':
        if (strcmp(eventSubType, "PlaySoundFX") == 0) {
            EventActionOneString stringParam;
            stringParam.param0 = params;
            if (soundArray != 0) {
                zEntEvent(soundArray->id, 0xDC750B31,
                          (Sext::EventAny*)&stringParam);
            }
        } else if (strcmp(eventSubType, "StopSoundFX") == 0) {
            EventActionOneString stringParam;
            stringParam.param0 = params;
            if (soundArray != 0) {
                zEntEvent(soundArray->id, 0x6A05C10F,
                          (Sext::EventAny*)&stringParam);
            }
        } else if (strcmp(eventSubType, "SetSoundFXVolume") == 0) {
            GlobalGetSoundModule()->SetMasterVolumeSFX(xStrParseFloat(params));
        } else if (strcmp(eventSubType, "SetMusicVolume") == 0) {
            GlobalGetSoundModule()->SetMasterVolumeMusic(
                xStrParseFloat(params));
        } else if (strcmp(eventSubType, "SetCinematicVolume") == 0) {
            GlobalGetSoundModule()->SetMasterVolumeCine(xStrParseFloat(params));
        } else if (strcmp(eventSubType, "SetDialogVolume") == 0) {
            GlobalGetSoundModule()->SetMasterVolumeDialog(
                xStrParseFloat(params));
        } else if (strcmp(eventSubType, "PlaySoundFXRemote") == 0) {
        }
        break;

    case 'TIKI':
        if (strcmp(eventSubType, "Yes") == 0) {
            zEntEventAllOfType(0, 0, 0x93D9DE68, 0, 221, (ForceEvent)1);
        } else if (strcmp(eventSubType, "No") == 0) {
            zEntEventAllOfType(0, 0, 0xCC1ADC8E, 0, 221, (ForceEvent)1);
        }
        break;

    case 'BUYS':
        if (strcmp(eventSubType, "Yes") == 0) {
            zEntEventAllOfType(0, 0, 0x42B85591, 0, 222, (ForceEvent)1);
        } else if (strcmp(eventSubType, "No") == 0) {
            zEntEventAllOfType(0, 0, 0x7AF953B7, 0, 222, (ForceEvent)1);
        } else if (strcmp(eventSubType, "SpendHappyPoints") == 0) {
            xCounter* ctr = (xCounter*)zSceneFindObject(
                "COLLECTIBLE_HAPPY_POINT_COUNTER_reference");
            ctr->count -= (short)atoi(params);
            zEntEventAllOfType(0, 0, 0xC40A65D2, 0, 219, (ForceEvent)1);
        }
        break;
    }
}

// ---- externalInterface's callees ---------------------------------------------

class GFxValue {
public:
    enum ValueType {
        VT_Undefined = 0,
        VT_Null = 1,
        VT_Boolean = 2,
        VT_Number = 3,
        VT_String = 4
    };

    union ValueUnion {
        double NValue;
        bool BValue;
        const char* pString;
    };

    ValueType GetType() const { return Type; }
    double GetNumber() const { return Value.NValue; }
    const char* GetString() const { return Value.pString; }

    void SetBoolean(bool v) {
        Type = VT_Boolean;
        Value.BValue = v;
    }

    void SetNumber(double v) {
        Type = VT_Number;
        Value.NValue = v;
    }

    void SetString(const char* s) {
        Type = VT_String;
        Value.pString = s;
    }

    ValueType Type;
    ValueUnion Value;
};

