void zScaleform::externalInterface(GFxValue* retVal, void* userData,
                                   const char* eventName, const GFxValue* args,
                                   unsigned int argCount) {
    strlen(eventName);

    const char* eventSubType = eventName + 5;

    switch (eventName[0] << 24 | eventName[1] << 16 | eventName[2] << 8 |
            eventName[3]) {
    case 'MENU':
        if (strcmp(eventSubType, "IsFirstBoot") == 0) {
            retVal->SetBoolean(true);
        } else if (strcmp(eventSubType, "GetString") == 0) {
            const char* retStr = NGStrings::FindString(args->GetString(), 0);
            if (retStr == 0) {
                retStr = args->GetString();
            }
            retVal->SetString(retStr);
        } else if (strcmp(eventSubType, "IsSubtitlesEnabled") == 0) {
            retVal->SetBoolean(globals.option_subtitles != 0);
        }
        break;

    case 'CHTS':
        if (strcmp(eventSubType, "GetNumCheats") == 0) {
            retVal->SetNumber(8.0);
        } else if (strcmp(eventSubType, "IsCheatEnabled") == 0) {
            unsigned int bitToCheck = (int)args->GetNumber();
            bool isCheatSet = (zCheatGetCheatFlags() & (1 << bitToCheck)) != 0;
            retVal->SetBoolean(isCheatSet);
        } else if (strcmp(eventSubType, "IsCheatUnlocked") == 0) {
            retVal->SetBoolean(
                zCheatIsCheatUnlocked((eCheats)(int)args->GetNumber()));
        }

    case 'CTRL':
        if (strcmp(eventSubType, "GetRumbleState") == 0) {
            retVal->SetBoolean(
                xRumble::Manager::Get()->IsRumblingEnabled(globals.playerPort));
        } else if (strcmp(eventSubType, "GetPrimaryController") == 0) {
            retVal->SetNumber(globals.playerPort);
        } else if (strcmp(eventSubType, "GetWiiMotionPlusCalibration") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetNumber(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v59());
        } else if (strcmp(eventSubType, "IsWaitingOnBackOut") == 0) {
            retVal->SetBoolean(
                TRC::MsgBoxManager::Instance()->IsBackoutMessageVisible());
        } else if (strcmp(eventSubType, "WasWiiNunchuckEnabled") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v83());
        } else if (strcmp(eventSubType, "WasWiiClassicControllerEnabled") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v46());
        } else if (strcmp(eventSubType, "WasGamecubeControllerEnabled") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v53());
        } else if (strcmp(eventSubType, "WasGameCubeButtonUsed") == 0) {
            retVal->SetBoolean(TRC::trcModule->trcPadManager.CheckHolding(
                (TRC::TRCPadManager::AccessoryType)4));
        } else if (strcmp(eventSubType, "WasClassicButtonUsed") == 0) {
            retVal->SetBoolean(TRC::trcModule->trcPadManager.CheckHolding(
                (TRC::TRCPadManager::AccessoryType)2));
        } else if (strcmp(eventSubType, "IsWiiNunchuckConnected") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v82());
        } else if (strcmp(eventSubType, "IsWiiClassicControllerConnected") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v44());
        } else if (strcmp(eventSubType, "IsWiiClassicControllerEnabled") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            if (TRC::trcModule->trcPadManager.CheckLockToHolding()) {
                retVal->SetBoolean(TRC::trcModule->trcPadManager.CheckHolding(
                    (TRC::TRCPadManager::AccessoryType)2));
            } else {
                retVal->SetBoolean(
                    zPlayerInputNS::GetPadAtGamePort(gamePort)->_v45());
            }
        } else if (strcmp(eventSubType, "IsWiiMotionPlusConnected") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            retVal->SetBoolean(zPlayerInputNS::GetPadAtGamePort(gamePort)->_v58());
        } else if (strcmp(eventSubType, "IsGamecubeControllerConnected") == 0 ||
                   strcmp(eventSubType, "IsGamecubeControllerEnabled") == 0) {
            int gamePort;
            if (args != 0 && args->GetType() == GFxValue::VT_Number) {
                gamePort = (int)args->GetNumber();
            } else {
                gamePort = globals.playerPort;
            }
            if (TRC::trcModule->trcPadManager.CheckLockToHolding()) {
                retVal->SetBoolean(TRC::trcModule->trcPadManager.CheckHolding(
                    (TRC::TRCPadManager::AccessoryType)4));
            } else {
                retVal->SetBoolean(
                    zPlayerInputNS::GetPadAtGamePort(gamePort)->_v52());
            }
        }
        break;

    case 'GAME':
        if (strcmp(eventSubType, "IsBiplane") == 0) {
            // NEAR MISS: 7 of 1074 words; retail keeps the type in r3 and the
            // player chain in r4, ours the other way. Tried the SetBoolean
            // inline, a bool local, a player local, a GetPlayer accessor, the
            // compare reversed, a ternary, and value-first stores.
            retVal->Type = GFxValue::VT_Boolean;
            retVal->Value.BValue = xglobals->players.playerArray[0]->eName == 5;
        } else if (strcmp(eventSubType, "GetSubGameType") == 0) {
            retVal->SetNumber(globals.subGameType);
        }
        break;

    case 'GLOB':
        if (strcmp(eventSubType, "GetMaxLevelUnlocked") == 0) {
        }

    case 'SCEN':
        if (strcmp(eventSubType, "GetLevelIndex") == 0) {
            retVal->SetNumber(zSceneGetLevelIndex());
        }
        break;

    case 'SYST':
        if (strcmp(eventSubType, "IsWii") == 0) {
            retVal->SetBoolean(true);
        } else if (strcmp(eventSubType, "IsX360") == 0) {
            retVal->SetBoolean(false);
        } else if (strcmp(eventSubType, "IsPS3") == 0) {
            retVal->SetBoolean(false);
        } else if (strcmp(eventSubType, "IsWideScreen") == 0) {
            retVal->SetBoolean(Scaleform::SFWrap_IsWidescreen());
        } else if (strcmp(eventSubType, "IsDemo") == 0) {
            retVal->SetBoolean(globals.demoType != 0);
        } else if (strcmp(eventSubType, "GetDemoType") == 0) {
            retVal->SetNumber(globals.demoType);
        } else if (strcmp(eventSubType, "GetLanguage") == 0) {
            retVal->SetString(xSTGetLocalizationCode());
        } else if (strcmp(eventSubType, "IsNunchukConnected") == 0) {
            retVal->SetBoolean(
                zPlayerInputNS::GetPadAtGamePort((int)args->GetNumber())->_v82());
        }
        break;

    case 'COLL':
        if (strcmp(eventSubType, "GetHappyPoints") == 0) {
            xCounter* ctr = (xCounter*)zSceneFindObject(
                "COLLECTIBLE_HAPPY_POINT_COUNTER_reference");
            retVal->SetNumber(ctr->count);
        } else if (strcmp(eventSubType, "GetCounterCount") == 0) {
            xCounter* counter = (xCounter*)zSceneFindObject(args->GetString());
            if (counter != 0) {
                retVal->SetNumber(counter->count);
            }
        } else if (strcmp(eventSubType, "ResetCounterCount") == 0) {
            xCounter* counter = (xCounter*)zSceneFindObject(args->GetString());
            counter->count = 0;
        } else if (strcmp(eventSubType, "GetSelectedCostume") == 0) {
            retVal->SetNumber(
                zPlayer::inventory.GetSelectedCostume((int)args->GetNumber()));
        } else if (strcmp(eventSubType, "SetSelectedCostume") == 0) {
            zPlayer::inventory.SetSelectedCostume((int)args[0].GetNumber(),
                                                  (int)args[1].GetNumber());
        } else if (strcmp(eventSubType, "IsCostumeBought") == 0) {
            retVal->SetBoolean(zPlayer::inventory.IsCostumeBought(
                (int)args[0].GetNumber(), (int)args[1].GetNumber()));
        } else if (strcmp(eventSubType, "SetCostumeBought") == 0) {
            zPlayer::inventory.SetCostumeBought((int)args[0].GetNumber(),
                                                (int)args[1].GetNumber());
        }
        break;

    case 'PLYR':
        if (strcmp(eventSubType, "GetMaxHealth") == 0) {
            retVal->SetNumber(
                ((zBoardPlayerVirtuals*)zBoardPlayer::GetInstance())
                    ->GetMaxHealth());
        } else if (strcmp(eventSubType, "GetNPCsKilled") == 0) {
            retVal->SetNumber(zBoardPlayer::GetInstance()->npcsKilled);
        }

    case 'SAVE':
        if (strcmp(eventSubType, "GetSlotStr") == 0) {
            int slotNumber = (int)args->GetNumber();
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slotNumber);
            const char* slotStr;
            zSceneReadHeader(header, &slotStr, 0);
            retVal->SetString(slotStr);
        } else if (strcmp(eventSubType, "IsSlotEmpty") == 0) {
            int slotNumber = (int)args->GetNumber();
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slotNumber);
            retVal->SetBoolean(header->empty != 0);
        } else if (strcmp(eventSubType, "GetSceneIdx") == 0) {
            int slot = argCount != 0 ? (int)args->GetNumber()
                                     : xglobals->autoSaveSlot;
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slot);
            int sceneIdx = header->sceneIdx;
            if (sceneIdx >= zDispatcherNS::maxLevel) {
                sceneIdx = zDispatcherNS::maxLevel - 1;
            }
            retVal->SetNumber(sceneIdx);
        } else if (strcmp(eventSubType, "GetHappyPoints") == 0) {
            int slot = argCount != 0 ? (int)args->GetNumber()
                                     : xglobals->autoSaveSlot;
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slot);
            retVal->SetNumber(header->happinessPoints);
        } else if (strcmp(eventSubType, "GetHappyObjects") == 0) {
            int slot = argCount != 0 ? (int)args->GetNumber()
                                     : xglobals->autoSaveSlot;
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slot);
            retVal->SetNumber(header->happinessObjects);
        } else if (strcmp(eventSubType, "GetLives") == 0) {
            int slot = argCount != 0 ? (int)args->GetNumber()
                                     : xglobals->autoSaveSlot;
            TRC::SaveDataHeader* header =
                TRC::trcModule->saveLoad.GetSaveDesc(slot);
            retVal->SetNumber(header->lives);
        }
        break;

    case 'SNDS':
        if (strcmp(eventSubType, "GetSoundFXVolume") == 0) {
            retVal->SetNumber(GlobalGetSoundModule()->sfxVolume);
        } else if (strcmp(eventSubType, "GetMusicVolume") == 0) {
            retVal->SetNumber(GlobalGetSoundModule()->musicVolume);
        } else if (strcmp(eventSubType, "GetCinematicVolume") == 0) {
            retVal->SetNumber(GlobalGetSoundModule()->cineVolume);
        } else if (strcmp(eventSubType, "GetDialogVolume") == 0) {
            retVal->SetNumber(GlobalGetSoundModule()->dialogVolume);
        }
        break;
    }
}

Graphics::Rect2D zScaleform::refreshViewport() {
    if (asset->viewnum == 4) {
        return ViewportFullUI.rect;
    }
    return viewports[asset->viewnum].viewportUI.rect;
}

void zScaleform::stopMovie() { moviePlaying = false; }
void zScaleform::movieStopped() { stoppedMovieCounter = 1; }

int zScaleform::getDisplayLayer() { return asset->renderLayer; }

bool zScaleform::IsPauseMoviePlaying() {
    bool playing = false;
    EmbeddedListNode* end = &globals.sceneCur->baseInfo[215].entz.head;
    for (EmbeddedListNode* node = end->next; node != end; node = node->next) {
        zScaleform* sf = (zScaleform*)((char*)node - 4);
        if (sf->moviePlaying && sf->asset->movieType == 4) {
            playing = true;
        }
    }
    return playing;
}

void zScaleform::PauseMoviesForTRC(bool pause) {
    zScene* scene = globals.sceneCur;
    if (scene != 0) {
        for (EmbeddedListNode* node = scene->baseInfo[215].entz.head.next;
             node != &scene->baseInfo[215].entz.head; node = node->next) {
            zScaleform* sf = (zScaleform*)((char*)node - 4);
            World::ScaleformOGAsset* og = sf;
            if (sf->asset->movieType == 4) {
                Scaleform::Coordinator::GetCoord()->SetPausedByTRC(og, pause);
            }
        }
    }
}

World::Entity* Sext::zScaleformAsset::Create(World::EntityHandleBase* handle,
                                             zScaleformAsset* asset) {
    zScaleform* sf = new (memset(
        Memory::AllocGlobalHeap(sizeof(zScaleform), (Memory::GlobalHeapEnum)0,
                                (eMemMgrTag)16, false),
        0, sizeof(zScaleform))) zScaleform(handle);
    zUI_Init(sf, asset);
    return (World::Entity*)sf;
}
